      en: ["The first fortification was built by French settlers in 1640.", "Abraham Crijnssen captured the fort for the Netherlands on February 25, 1667.", "The fortress features a distinctive pentagonal star-shaped design.", "During the 1980s, the fort served as the headquarters for the military council.", "The Suriname Museum has been located within the fort since 1995.", "The site is a key component of Paramaribo's UNESCO World Heritage inner city."],
      es: ["El fuerte sirvió durante siglos como centro administrativo de la colonia.", "Durante la dictadura militar se utilizó como prisión.", "Las antiguas murallas ofrecen una visión única de la arquitectura militar de la región.", "Un paseo por el fuerte es un viaje a través de toda la época colonial de Surinam."],
      pt: ["O forte serviu durante séculos como centro administrativo da colónia.", "Durante a ditadura militar foi utilizado como prisão.", "As antigas muralhas oferecem uma visão única da arquitetura militar da região.", "Um passeio pelo forte é uma viagem através de toda a era colonial do Suriname."],
