      es: ["Fundada en la década de 1750", "Se convirtió más tarde en una plantación de cacao", "Lápidas históricas conservadas"],
      pt: ["Fundada na década de 1750", "Tornou-se mais tarde uma plantação de cacau", "Lápides históricas preservadas"],
      fr: ["Fondée dans les années 1750", "Est devenue plus tard une plantation de cacao", "Pierres tombales historiques conservées"],
