    name: {
      de: "Plantage Waterland",
      hu: "Waterland Ültetvény",
      ro: "Plantația Waterland",
      en: "Waterland Plantation"},
    image: "/poi-images/sr-waterland-history-v2.webp",
    description: {
      de: "Einst eine florierende Zuckerrohrplantage, heute ein beliebtes historisches Erholungsgebiet am Fluss.",
      hu: "Egykor virágzó cukornádültetvény, ma népszerű történelmi pihenőövezet a folyó mentén.",
      ro: "Odinioară o înfloritoare plantație de trestie de zahăr, astăzi o populară zonă istorică de recreere pe râu.",
      en: "Once a flourishing sugar cane plantation, today a popular historic recreation area along the river.",
      es: "Antiguamente una floreciente plantación de caña de azúcar, hoy un popular y recreativo sitio histórico a orillas del río.",
      pt: "Antigamente uma próspera plantação de cana-de-açúcar, hoje um popular e recreativo local histórico junto ao rio.",
      fr: "Autrefois une plantation de canne à sucre florissante, aujourd'hui un lieu historique récréatif populaire au bord de la rivière.",
    },
    descriptionAdvanced: {
      de: "Die Plantage Waterland am rechten Ufer des Suriname-Flusses ist ein historisches Areal, das den Wandel von einer kolonialen Zuckerplantage zu einem modernen Erholungsort vollzogen hat. Gegründet in der Mitte des 18. Jahrhunderts, war Waterland über lange Zeit ein wichtiger Produzent von Rohrzucker und später Kaffee. Die geografische Lage direkt am Fluss machte die Plantage zu einem wichtigen logistischen Knotenpunkt für den Abtransport der Waren nach Paramaribo. Nach der Abschaffung der Sklaverei und dem darauffolgenden wirtschaftlichen Niedergang der klassischen Plantagenwirtschaft wurde das Gelände im 20. Jahrhundert verschiedenen Nutzungen zugeführt. Heute ist Waterland vor allem für seinen exklusiven Resort-Charakter bekannt, wobei die historischen Wurzeln durch Informationstafeln und erhaltene Gräber der ehemaligen Besitzerfamilien gewürdigt werden. Die Kombination aus tropischer Natur, Flussnähe und der Ruhe fernab der Hauptstadt macht den Ort zu einem beliebten Ziel für Inlandstourismus. Die Entwicklung von Waterland zeigt beispielhaft, wie historisches Gelände für die heutige Freizeitgesellschaft transformiert werden kann, ohne seine Identität ganz zu verlieren.",
      hu: "A Waterland ültetvény a Suriname-folyó jobb partján fekszik, és egy olyan történelmi terület, amely sikeresen alakult át gyarmati cukorültetvényből modern üdülőhellyé. A 18. század közepén alapított Waterland hosszú ideig a nádcukor, majd később a kávé jelentős termelője volt. A folyó menti elhelyezkedése fontos logisztikai központtá tette, ahonnan az árukat könnyen szállíthatták Paramaribóba. A rabszolgaság eltörlése és az ültetvényi rendszer gazdasági hanyatlása után a 20. században a területet különböző célokra hasznosították. Napjainkban Waterland elsősorban exkluzív üdülőhelyként ismert, ahol információs táblák és az egykori tulajdonos családok fennmaradt sírjai emlékeztetnek a múltra. A trópusi természet, a folyó közelsége és a fővárostól való távolság miatt a helyszín a belföldi turizmus kedvelt célpontja. Waterland fejlődése jól példázza, hogyan lehet a történelmi helyszíneket a modern szabadidős igényekhez igazítani anélkül, hogy történelmi identitásukat teljesen elveszítenék.",
      ro: "Plantația Waterland, situată pe malul drept al râului Suriname, este un domeniu istoric care a trecut prin transformarea de la o plantație colonială de zahăr la o stațiune modernă de recreere. Fondată la mijlocul secolului al XVIII-lea, Waterland a fost mult timp un producător important de zahăr din trestie și ulterior de cafea. Poziția sa geografică direct pe râu a făcut din plantație un punct logistic esențial pentru transportul mărfurilor către Paramaribo. După abolirea sclaviei și declinul economic al sistemului de plantații, terenul a avut diverse utilizări în secolul al XX-lea. Astăzi, Waterland este cunoscut în principal pentru complexul său turistic exclusivist, rădăcinile istorice fiind onorate prin panouri informative și mormintele conservate ale foștilor proprietari. Combinația de natură tropicală, proximitatea râului și liniștea departe de capitală fac din acest loc o destinație populară pentru turismul intern. Evoluția plantației Waterland exemplifică modul în care terenurile istorice pot fi adaptate pentru societatea contemporană, păstrându-și totodată identitatea.",
      en: "Waterland Plantation, situated on the right bank of the Suriname River, is a historical estate that has successfully transitioned from a colonial sugar plantation to a modern recreational destination. Founded in the mid-18th century, Waterland was for a long period a significant producer of cane sugar and later coffee. Its geographic location directly on the river made it a vital logistical hub for transporting goods to Paramaribo. Following the abolition of slavery and the subsequent economic decline of the traditional plantation system, the land saw various uses throughout the 20th century. Today, Waterland is primarily known as an upscale river resort, where its historical roots are commemorated through information markers and the preserved graves of former owner families. The combination of tropical nature, riverfront access, and its tranquil setting away from the capital makes it a favorite spot for domestic tourism. The development of Waterland serves as an example of how historic plantation sites can be repurposed for modern leisure while maintaining a connection to their historical legacy.",
      es: "Waterland ofrece una mezcla única de encanto histórico y recreación natural a orillas del río Surinam. Conocido originalmente como una exitosa plantación de caña de azúcar, el lugar se ha convertido en un destino popular para las personas que buscan paz y desean respirar la historia del país. La interacción entre la estructura histórica conservada y la exuberante naturaleza a lo largo del río convierte a Waterland en una joya. Los visitantes pueden encontrar aquí el equilibrio entre actividades de ocio relajadas y el acercamiento al pasado industrial de Surinam. Waterland es hoy un lugar que muestra cómo los sitios históricos pueden transformarse en la modernidad.",
      pt: "Waterland oferece uma mistura única de charme histórico e recreação natural junto ao rio Suriname. Conhecido originalmente como uma plantação de cana-de-açúcar bem-sucedida, o local tornou-se um destino popular para as pessoas que procuram paz e desejam respirar a história do país. A interação entre a estrutura histórica preservada e a natureza exuberante ao longo do rio torna Waterland uma joia. Os visitantes podem encontrar aqui o equilíbrio entre atividades de lazer relaxadas e a abordagem ao passado industrial do Suriname. Waterland é hoje um local que mostra como os sítios históricos podem transformar-se na modernidade.",
      fr: "Waterland offre un mélange unique de charme historique et de loisirs naturels au bord de la rivière Suriname. Connu à l'origine comme une plantation de canne à sucre prospère, le lieu est devenu une destination populaire pour ceux qui recherchent la tranquillité et souhaitent s'imprégner de l'histoire du pays. L'interaction entre la structure historique préservée et la nature luxuriante le long de la rivière fait de Waterland un joyau. Les visiteurs peuvent y trouver un équilibre entre activités de loisirs détendues et découverte du passé industriel du Suriname. Waterland est aujourd'hui un lieu qui montre comment les sites historiques peuvent être transformés dans la modernité.",
    },
