      hu: ["Az ültetvényt már 1750 előtt említik cukornádültetvényként.", "A 18. században hosszú ideig a Neale család volt a tulajdonos.", "Waterland körülbelül 30 kilométerre délre fekszik Paramaribótól.", "A mai üdülőhelyet a 2010-es években modernizálták.", "A területen gyarmati korból származó sírkövek találhatók.", "Az ültetvény kedvelt kikötőhely a vitorlázók és hajós kirándulók számára."],
      ro: ["Plantația a fost menționată ca fiind de trestie de zahăr înainte de 1750.", "În secolul al XVIII-lea, familia Neale a fost proprietară pentru mult timp.", "Waterland se află la circa 30 de kilometri sud de capitala Paramaribo.", "Complexul turistic actual a fost modernizat în anii 2010.", "Pe domeniu se găsesc pietre funerare din perioada colonială.", "Plantația este o locație populară pentru navigatori și excursii cu barca."],
      en: ["The plantation was mentioned as a sugar estate as early as 1750.", "In the 18th century, the Neale family were long-term owners.", "Waterland is located about 30 kilometers south of Paramaribo.", "The current resort underwent significant modernization in the 2010s.", "Historic gravestones from the colonial era are still on the grounds.", "The plantation is a popular destination for sailors and boat excursions."],
      es: ["Waterland ofrece a los visitantes acceso a una variedad de actividades, incluyendo paseos en barco y senderismo."],
