    image: "/poi-images/sr-laarwijk-history-v2.webp",
    description: {
      de: "Eine historische Siedlung, die nur mit dem Boot erreichbar ist, geprägt von landwirtschaftlicher Geschichte.",
      hu: "Egy történelmi település, amely csak hajóval közelíthető meg, és mezőgazdasági múltja határozza meg.",
      ro: "O așezare istorică accesibilă doar cu barca, caracterizată prin istoria sa agricolă.",
      en: "A historic settlement accessible only by boat, characterized by its agricultural history.",
      es: "Un asentamiento histórico al que solo se puede llegar en barco, caracterizado por su historia agrícola.",
      pt: "Um assentamento histórico que só pode ser alcançado de barco, caracterizado por sua história agrícola.",
      fr: "Un établissement historique accessible uniquement par bateau, marqué par une histoire agricole.",
    },
    descriptionAdvanced: {
      de: "Laarwijk ist eine historische Plantage am rechten Ufer des Suriname-Flusses, die heute als lebendige Dorfgemeinschaft fortbesteht. Gegründet im 18. Jahrhundert, war sie zunächst auf den Anbau von Kaffee und Zitrusfrüchten spezialisiert. Nach dem Ende der Sklaverei im Jahr 1863 wurde die Plantage von ehemaligen Sklaven und später von Vertragsarbeitern gemeinschaftlich genutzt, was zur Entstehung einer autonomen Siedlungsstruktur führte. Die Region ist bekannt für ihre fruchtbaren Böden, die noch heute für den Anbau von Orangen und anderen tropischen Früchten genutzt werden. Laarwijk zeichnet sich durch seine abgeschiedene Lage aus, da es keine direkte Straßenverbindung gibt und das Dorf nur per Boot erreichbar ist. Dies hat dazu beigetragen, dass traditionelle Lebensweisen und die enge Bindung zur Natur erhalten geblieben sind. In den letzten Jahren hat sich in Laarwijk ein sanfter Tourismus entwickelt, der Besuchern Einblicke in das authentische Landleben Surinames und die Geschichte der kleinbäuerlichen Landwirtschaft nach der Plantagenära bietet. Das Projekt 'Laarwijk Schoon' fördert zudem die ökologische Nachhaltigkeit und den Umweltschutz in der Gemeinde.",
      hu: "A Laarwijk egy történelmi ültetvény a Suriname-folyó jobb partján, amely ma élő faluközösségként működik tovább. A 18. században alapították, és eredetileg kávé- valamint citrusfélék termesztésére szakosodott. A rabszolgaság 1863-as eltörlése után az ültetvényt egykori rabszolgák és később szerződéses munkások vették birtokba, ami egy autonóm településszerkezet kialakulásához vezetett. A régió híres termékeny talajáról, amelyet ma is narancs és más trópusi gyümölcsök termesztésére használnak. Laarwijk különlegessége az elszigeteltsége, mivel nincs közvetlen közúti összeköttetése, és csak csónakkal érhető el. Ez segített megőrizni a hagyományos életmódot és a természettel való szoros kapcsolatot. Az elmúlt években Laarwijkban fejlődésnek indult a fenntartható turizmus, amely lehetőséget ad a látogatóknak, hogy megismerjék az autentikus vidéki Suriname-ot és a kisparcellás gazdálkodás történetét az ültetvényi korszak után. A 'Laarwijk Schoon' projekt emellett az ökológiai fenntarthatóságot és a környezetvédelmet népszerűsíti a közösségben.",
      ro: "Laarwijk este o plantație istorică situată pe malul drept al râului Suriname, care continuă să existe astăzi ca o comunitate rurală vibrantă. Fondată în secolul al XVIII-lea, aceasta a fost inițial specializată în cultivarea cafelei și a citricelor. După abolirea sclaviei în 1863, plantația a fost utilizată în comun de foștii sclavi și, ulterior, de lucrătorii contractuali, ceea ce a dus la formarea unei structuri de așezare autonome. Regiunea este cunoscută pentru solurile sale fertile, care sunt folosite și în prezent pentru cultivarea portocalelor și a altor fructe tropicale. Laarwijk se remarcă prin izolarea sa, neexistând o conexiune rutieră directă, satul fiind accesibil doar cu barca. Acest fapt a contribuit la păstrarea modului de viață tradițional și a legăturii strânse cu natura. În ultimii ani, în Laarwijk s-a dezvoltat un turism sustenabil, oferind vizitatorilor o privire asupra vieții rurale autentice din Suriname și a istoriei micii agriculturi de după era plantațiilor. Proiectul 'Laarwijk Schoon' promovează sustenabilitatea ecologică și protecția mediului în cadrul comunității.",
      en: "Laarwijk is a historic plantation on the right bank of the Suriname River that continues to thrive today as a vibrant village community. Established in the 18th century, it was originally specialized in the cultivation of coffee and citrus fruits. Following the end of slavery in 1863, the plantation was utilized by former enslaved people and later by indentured laborers, leading to the development of an autonomous settlement structure. The region is famous for its fertile soil, which is still used today for the production of oranges and other tropical fruits. Laarwijk is characterized by its relative isolation, as there is no direct road connection and the village is accessible only by boat across the river. This seclusion has helped preserve traditional ways of life and a strong connection to the natural environment. In recent years, Laarwijk has seen the emergence of sustainable community-based tourism, offering visitors insights into authentic rural Surinamese life and the history of small-scale farming in the post-plantation era. The 'Laarwijk Schoon' initiative further promotes ecological sustainability and environmental protection within the community.",
      es: "Laarwijk es una joya oculta profundamente arraigada en la tradición agrícola de Surinam. Accesible solo por vía acuática, este asentamiento conserva un carácter auténtico que aleja a los visitantes del bullicio urbano. El pasado agrícola, que aún hoy se siente en la estructura y las formas de vida de los habitantes, convierte a Laarwijk en un lugar de desaceleración. Las esclusas históricas y el cultivo tradicional de la tierra ofrecen una visión fascinante de un mundo donde el ritmo de la naturaleza sigue determinando la vida. Es un oasis que ha conservado especialmente su encanto histórico gracias a su aislamiento.",
      pt: "Laarwijk é uma joia escondida profundamente enraizada na tradição agrícola do Suriname. Acessível apenas por via aquática, este assentamento preserva um caráter autêntico que leva os visitantes para longe da agitação urbana. O passado agrícola, que ainda hoje se sente na estrutura e nas formas de vida dos habitantes, faz de Laarwijk um lugar de desaceleração. As eclusas históricas e o cultivo tradicional da terra oferecem uma visão fascinante de um mundo onde o ritmo da natureza ainda determina a vida. É um oásis que preservou especialmente o seu charme histórico graças ao seu isolamento.",
      fr: "Laarwijk est un joyau caché profondément enraciné dans la tradition agricole du Suriname. Accessible uniquement par voie d'eau, cet établissement conserve un caractère authentique qui éloigne les visiteurs de l'agitation urbaine. Le passé agricole, encore perceptible aujourd'hui dans la structure et les modes de vie des habitants, fait de Laarwijk un lieu de ralentissement. Les écluses historiques et la culture traditionnelle des terres offrent un aperçu fascinant d'un monde où le rythme de la nature détermine encore la vie. C'est une oasis qui a particulièrement préservé son charme historique grâce à son isolement.",
    },
