      de: ["Gegründet im Jahr 1747 durch den Gouverneur Wigbold Crommelin.", "Ursprünglich eine kombinierte Zucker-, Kaffee- und Kakao-Plantage.", "Beheimatet heute einen der größten Rinderzuchtbetriebe Surinames.", "Nach 1863 siedelten sich hier viele javanische Vertragsarbeiter an.", "Die Plantage liegt strategisch am rechten Ufer des Suriname-Flusses.", "Verfügt über historische Fabrikruinen und koloniale Entwässerungssysteme."],
