      ro: ["Fondată în anul 1747 de către guvernatorul Wigbold Crommelin.", "Inițial a fost o plantație mixtă de zahăr, cafea și cacao.", "Găzduiește astăzi una dintre cele mai mari ferme de bovine din Surinam.", "După anul 1863, mulți lucrători javanezi s-au stabilit în această zonă.", "Plantația este situată pe malul drept al râului Surinam.", "Păstrează ruine ale vechilor fabrici și sisteme de drenaj coloniale."],
      en: ["Established in 1747 by Governor Wigbold Crommelin.", "Originally functioned as a mixed sugar, coffee, and cocoa estate.", "Currently home to one of the largest cattle ranches in Suriname.", "Attracted many Javanese indentured laborers after the 1863 abolition.", "The plantation is situated on the right bank of the Suriname River.", "Features historic factory ruins and colonial-era drainage systems."],
      es: ["El lugar es un ejemplo vivo de la transformación de las estructuras agrarias."],
      pt: ["O local é um exemplo vivo da transformação das estruturas agrárias."],
      fr: ["Le lieu est un exemple vivant de la transformation des structures agraires."],
