      ro: ["Creată în 1936 prin fuziunea a cinci plantații istorice mai mici.", "Este astăzi unul dintre cei mai mari producători de citrice ai statului.", "Localitatea este accesibilă exclusiv pe apă, pe râul Commewijne.", "Locuitorii sunt preponderent urmași ai muncitorilor javanezi.", "Așezarea păstrează arhitectura tipică din lemn de la începutul secolului XX.", "Joacă un rol strategic în securitatea alimentară a Surinamului."],
      en: ["Formed in 1936 by merging five smaller historical plantations.", "Currently serves as one of Suriname's largest state-owned citrus producers.", "The settlement is accessible only by boat via the Commewijne River.", "The inhabitants are mostly descendants of Javanese indentured laborers.", "The village preserves typical early 20th-century wooden architecture.", "Alliance plays a strategic role in the national supply of oranges."],
      es: ["Alliance es un ejemplo importante de agricultura apoyada por el estado."],
      pt: ["Alliance é um exemplo importante da agricultura apoiada pelo Estado."],
