      en: ["Established in the 18th century by Samuel de la Parra.", "The name is French in origin, meaning My Retreat.", "Originally operated as a major plantation for sugar production.", "Gradually converted into a residential area during the 20th century.", "Currently regarded as one of Paramaribo's most exclusive neighborhoods.", "The old plantation canals now serve as part of the city drainage system."],
      es: ["El nombre del distrito es el último gran vestigio de la antigua plantación."],
