      ro: ["Fostă plantație de cafea", "Numită după proprietarul francez", "Astăzi un cartier rezidențial popular"],
      en: ["Former coffee plantation", "Named after the French owner", "Today a popular residential area"],
      es: ["Antigua plantación de café", "Nombrada en honor al propietario francés", "Hoy es un barrio residencial popular"],
      pt: ["Antiga plantação de café", "Nomeada em honra do proprietário francês", "Hoje é um bairro residencial popular"],
      fr: ["Ancienne plantation de café", "Nommée en l'honneur du propriétaire français", "Aujourd'hui un quartier résidentiel populaire"],
