    image: "/poi-images/sr-zorg-en-hoop-history-v2.webp",
    description: {
      de: "Ein historisches Viertel in Paramaribo, das aus einer alten Plantage entstand und den ersten Flugplatz der Stadt beherbergt.",
      hu: "Paramaribo egyik történelmi negyede, amely egy régi ültetvényből nőtt ki, és a város első repülőterének ad otthont.",
      ro: "Un cartier istoric din Paramaribo care s-a dezvoltat dintr-o veche plantație și găzduiește primul aerodrom al orașului.",
      en: "A historic district in Paramaribo that grew out of an old plantation and is home to the city's first airfield.",
      es: "Un barrio histórico en Paramaribo, que surgió de una antigua plantación y alberga el primer aeródromo de la ciudad.",
      pt: "Um bairro histórico em Paramaribo, que surgiu de uma antiga plantação e alberga o primeiro aeródromo da cidade.",
      fr: "Un quartier historique de Paramaribo, qui a émergé d'une ancienne plantation et abrite le premier aérodrome de la ville.",
    },
    descriptionAdvanced: {
      de: "Zorg en Hoop wurde im Jahr 1793 als Plantage am Rande von Paramaribo gegründet und diente über Jahrzehnte hinweg der Produktion von Zucker und anderen Exportgütern. Der Name, der Sorge und Hoffnung bedeutet, reflektiert die unsicheren wirtschaftlichen Aussichten der kolonialen Landwirtschaft jener Zeit. Im 20. Jahrhundert erlebte der Standort eine radikale Transformation, als ein Teil des Geländes für den Bau des Flughafens Zorg en Hoop genutzt wurde, der 1952 offiziell eröffnet wurde. Heute ist das Viertel ein pulsierendes Zentrum, das den wichtigsten Inlandsflughafen Surinames beherbergt und somit eine zentrale Rolle für die Verbindung zum Hinterland spielt. Neben dem Flugbetrieb haben sich hier bedeutende Bildungseinrichtungen, Sportkomplexe und Wohngebiete etabliert, was Zorg en Hoop zu einem vielseitigen Stadtteil macht. Die historische Verbindung zur Plantagenzeit ist in der Namensgebung und einigen verbliebenen Grünflächen erhalten geblieden. Als Knotenpunkt für den Regionalverkehr und Sitz zahlreicher Institutionen ist Zorg en Hoop heute ein unverzichtbarer Teil der Infrastruktur der surinamischen Hauptstadt.",
      hu: "A Zorg en Hoop ültetvényt 1793-ban alapították Paramaribo szélén, és évtizedeken át cukor és egyéb exportcikkek termelését szolgálta. A név, amely Aggodalmat és Reményt jelent, a korabeli gyarmati mezőgazdaság bizonytalan gazdasági kilátásait tükrözi. A 20. században a helyszín radikális átalakuláson ment keresztül, amikor a terület egy részét a Zorg en Hoop repülőtér építésére használták fel, amelyet 1952-ben nyitottak meg hivatalosan. Ma a negyed egy lüktető központ, amely Suriname legfontosabb belföldi repülőterének ad otthont, így központi szerepet játszik a belső területekkel való kapcsolattartásban. A repülés mellett jelentős oktatási intézmények, sportkomplexumok és lakóövezetek is megtelepedtek itt, ami sokszínű városrésszé teszi a Zorg en Hoop-ot. Az ültetvénykorszakkal való történelmi kapcsolat a névválasztásban és néhány megmaradt zöldfelületben maradt fenn. A regionális közlekedés csomópontjaként és számos intézmény székhelyeként a Zorg en Hoop ma a suriname-i főváros infrastruktúrájának nélkülözhetetlen része.",
      ro: "Zorg en Hoop a fost fondată în anul 1793 ca o plantație la periferia orașului Paramaribo și a servit timp de decenii producției de zahăr și altor bunuri de export. Numele, care înseamnă Grijă și Speranță, reflectă perspectivele economice incerte ale agriculturii coloniale din acea perioadă. În secolul XX, locația a suferit o transformare radicală când o parte din teren a fost utilizată pentru construcția aeroportului Zorg en Hoop, deschis oficial în 1952. Astăzi, cartierul este un centru vibrant care găzduiește cel mai important aeroport intern din Surinam, jucând astfel un rol central în conexiunea cu interiorul țării. Pe lângă operațiunile aeriene, aici s-au stabilit instituții educaționale importante, complexe sportive și zone rezidențiale, ceea ce face din Zorg en Hoop un cartier versatil. Legătura istorică cu perioada plantațiilor s-a păstrat în denumire și în câteva spații verzi rămase. Ca nod pentru traficul regional și sediu al numeroaselor instituții, Zorg en Hoop este astăzi o parte indispensabilă a infrastructurii capitalei surinameze.",
      en: "Zorg en Hoop was established in 1793 as a plantation on the outskirts of Paramaribo and served for decades in the production of sugar and other export goods. The name, which means Care and Hope, reflects the uncertain economic prospects of colonial agriculture during that era. In the 20th century, the site underwent a radical transformation when part of the land was used for the construction of the Zorg en Hoop Airport, which officially opened in 1952. Today, the neighborhood is a pulsating hub housing Suriname's most important domestic airport, thereby playing a central role in connecting the capital with the interior. In addition to aviation, significant educational institutions, sports complexes, and residential areas have established themselves here, making Zorg en Hoop a diverse district. The historical link to the plantation era is preserved in its name and a few remaining green spaces. As a hub for regional transport and the seat of numerous institutions, Zorg en Hoop is now an indispensable part of the infrastructure of the Surinamese capital.",
      es: "Zorg en Hoop es un barrio en Paramaribo que encarna la fascinante conexión entre el patrimonio histórico y la movilidad moderna. El nombre del distrito, que designa una antigua plantación, da testimonio del pasado agrícola. Pero el barrio también es conocido como la sede del Aeropuerto Zorg en Hoop, que desempeña un papel central para conectar a Surinam con su interior. La mezcla de casas coloniales tradicionales y la historia moderna de la aviación hace de este distrito un lugar único donde se puede experimentar la evolución histórica y el comienzo de la modernidad en un espacio reducido.",
      pt: "Zorg en Hoop é um bairro em Paramaribo que encarna a fascinante conexão entre o património histórico e a mobilidade moderna. O nome do distrito, que designa uma antiga plantação, dá testemunho do passado agrícola. Mas o bairro também é conhecido como a sede do Aeroporto Zorg en Hoop, que desempenha um papel central para ligar o Suriname com o seu interior. A mistura de casas coloniais tradicionais e a história moderna da aviação faz deste distrito um local único onde se pode experimentar a evolução histórica e o início da modernidade num espaço reduzido.",
      fr: "Zorg en Hoop est un quartier de Paramaribo qui incarne la connexion fascinante entre l'héritage historique et la mobilité moderne. Le nom du quartier, qui désigne une ancienne plantation, témoigne du passé agricole. Mais le quartier est également connu comme le siège de l'aéroport Zorg en Hoop, qui joue un rôle central pour relier le Suriname à son arrière-pays. Le mélange de maisons coloniales traditionnelles et de l'histoire moderne de l'aviation fait de ce quartier un lieu unique où l'on peut vivre l'évolution historique et l'éveil à la modernité dans un espace réduit.",
    },
