      en: ["Established in 1793 as a sugar plantation near Paramaribo.", "The name translates from Dutch as Care and Hope.", "Has hosted the country's main domestic airport since 1952.", "Serves as the central hub for flights into the tropical rainforest.", "The district now encompasses parts of the University of Suriname.", "Features significant sports facilities like the national stadium."],
