    coords: [-55.186, 5.828],
    name: {
      de: "Arya Dewaker Tempel",
      hu: "Arya Dewaker Templom",
      ro: "Templul Arya Dewaker",
      en: "Arya Dewaker Temple"},
    image: "/poi-images/sr-arya-dewaker-history-v2.webp",
    description: {
      de: "Einer der größten hinduistischen Tempel in Suriname mit einer einzigartigen oktogonalen Architektur.",
      hu: "Suriname egyik legnagyobb hindu temploma, egyedi nyolcszögletű építészettel.",
      ro: "Unul dintre cele mai mari temple hinduse din Suriname, cu o arhitectură octogonală unică.",
      en: "One of the largest Hindu temples in Suriname with unique octagonal architecture.",
      es: "Uno de los templos hindúes más grandes de Surinam con una arquitectura octogonal única.",
      pt: "Um dos maiores templos hindus do Suriname com uma arquitetura octogonal única.",
      fr: "L'un des plus grands temples hindous du Suriname avec une architecture octogonale unique.",
    },
    descriptionAdvanced: {
      de: "Der Tempel Arya Dewaker ist das größte hinduistische Gotteshaus in Suriname und befindet sich in der Hauptstadt Paramaribo. Er wurde von dem niederländischen Architekten Arthur E. de Groot entworfen und am 11. Februar 2001 offiziell eingeweiht. Das Bauwerk gehört zur Arya-Samaj-Bewegung, einer hinduistischen Reformgruppe, die die Verehrung von Götterbildern ablehnt, weshalb im Inneren keine Statuen von Gottheiten zu finden sind. Die Architektur kombiniert niederländische Bauelemente mit indo-sarazenischen Einflüssen und verfügt über zwei achteckige Hauptgebäude mit markanten Kuppeln. Der Tempel bietet Platz für rund 1500 Gläubige und dient als zentrales religiöses und kulturelles Zentrum für die indische Gemeinschaft in Suriname. Die weiße Fassade und die sorgfältigen geometrischen Verzierungen machen das Gebäude zu einem architektonischen Wahrzeichen der Stadt.",
      hu: "Az Arya Dewaker templom Suriname legnagyobb hindu vallási épülete, amely a fővárosban, Paramaribóban található. Az épületet Arthur E. de Groot holland építész tervezte, és 2001. február 11-én adták át ünnepélyesen. A templom az Arya Samaj mozgalomhoz tartozik, amely egy hindu reformcsoport; hitük szerint elvetik az istenszobrok imádatát, így a belső térben nincsenek kegytárgyak vagy istenségek képmásai. Az építészeti stílus a holland elemeket ötvözi az indo-szaracén hatásokkal, két nyolcszögletű épületrészből áll, amelyeket jellegzetes kupolák díszítenek. A templom befogadóképessége körülbelül 1500 fő, és fontos kulturális találkozóhelyként szolgál a suriname-i indiai közösség számára. Fehér homlokzata és szimmetrikus kialakítása Paramaribo egyik legmeghatározóbb városképi elemévé teszi.",
      ro: "Templul Arya Dewaker este cel mai mare lăcaș de cult hindu din Suriname, situat în capitala Paramaribo. Clădirea a fost proiectată de arhitectul olandez Arthur E. de Groot și a fost inaugurată oficial la 11 februarie 2001. Acesta aparține mișcării Arya Samaj, un grup de reformă hindu care respinge venerarea imaginilor zeităților, motiv pentru care interiorul nu conține statui ale zeilor. Arhitectura combină elemente de design olandez cu influențe indo-sarazine, având două clădiri principale octogonale cu cupole distinctive. Templul are o capacitate de aproximativ 1500 de persoane și servește ca un centru religios și cultural vital pentru comunitatea indiană din Suriname. Fațada sa albă și ornamentele geometrice precise fac din această structură un reper arhitectural important în peisajul urban al capitalei.",
      en: "The Arya Dewaker Temple is the largest Hindu place of worship in Suriname, located in the capital city of Paramaribo. Designed by Dutch architect Arthur E. de Groot, the temple complex was officially dedicated on February 11, 2001. It belongs to the Arya Samaj movement, a Hindu reform group that rejects the worship of idols; consequently, the interior contains no statues of deities, focusing instead on abstract symbolism. The architecture blends Dutch structural elements with Indo-Saracenic influences, featuring two main octagonal buildings topped with prominent domes. The temple can accommodate approximately 1,500 worshippers and serves as a major cultural and religious hub for the Indo-Surinamese population. Its striking white exterior and intricate geometric patterns make it one of the most significant architectural landmarks in the country.",
      es: "El templo Arya Dewaker en Paramaribo es un ejemplo impresionante de la diversidad religiosa y cultural de Surinam. Su arquitectura octogonal única simboliza la armonía de las diferentes corrientes dentro del hinduismo y ofrece un centro espiritual para el movimiento Arya Samaj en el país. Desde su inauguración en 2001, el templo se ha establecido como un lugar que no solo atrae a los fieles, sino que también representa un punto culminante arquitectónico. La combinación de elementos de estilo indio y surinamés subraya el profundo arraigo de la población de origen indio en la sociedad surinamés. Por lo tanto, el templo es mucho más que un edificio; es un símbolo vivo de la integración cultural y la identidad espiritual en un entorno multicultural.",
      pt: "O templo Arya Dewaker em Paramaribo é um exemplo impressionante da diversidade religiosa e cultural do Suriname. A arquitetura octogonal única simboliza a harmonia das diferentes correntes dentro do hinduísmo e oferece um centro espiritual para o movimento Arya Samaj no país. Desde a sua inauguração em 2001, o templo estabeleceu-se como um lugar que não só atrai fiéis, mas também representa um destaque arquitetónico. A combinação de elementos de estilo indiano e surinamês sublinha o profundo enraizamento da população de origem indiana na sociedade surinamesa. O templo é, portanto, muito mais do que apenas um edifício; é um símbolo vivo da integração cultural e da identidade espiritual num ambiente multicultural.",
      fr: "Le temple Arya Dewaker à Paramaribo est un exemple impressionnant de la diversité religieuse et culturelle du Suriname. Son architecture octogonale unique symbolise l'harmonie des différents courants au sein de l'hindouisme et offre un centre spirituel pour le mouvement Arya Samaj dans le pays. Depuis son inauguration en 2001, le temple s'est imposé comme un lieu qui attire non seulement les fidèles, mais qui représente également un point fort architectural. La combinaison d'éléments de style indien et surinamais souligne le profond enracinement de la population d'origine indienne dans la société surinamaise. Le temple est donc bien plus qu'un simple bâtiment ; c'est un symbole vivant de l'intégration culturelle et de l'identité spirituelle dans un environnement multiculturel.",
    },
