      ro: ["Construită în anul 1719", "Podeaua de nisip amintește de Exod", "Situată chiar lângă o moschee"],
      en: ["Built in 1719", "Sand floor recalls the Exodus", "Located right next to a mosque"],
      es: ["Construida en 1719", "El suelo de arena recuerda el Éxodo", "Situada justo al lado de una mezquita"],
      pt: ["Construída em 1719", "O solo de areia lembra o Êxodo", "Localizada ao lado de uma mesquita"],
      fr: ["Construite en 1719", "Le sol de sable rappelle l'Exode", "Située juste à côté d'une mosquée"],
