      pt: ["Maior mercado coberto das Caraíbas", "Lugar de comércio e cultura", "Secção partilhada do mercado das bruxas"],
      fr: ["Plus grand marché couvert des Caraïbes", "Lieu de commerce et de culture", "Section partagée du marché aux sorcières"],
