      hu: ["Suriname legnagyobb piaca", "A Suriname-folyó partján fekszik", "Különleges maroon gyógynövénypiaca van", "A halat közvetlenül a hajókról szállítják", "Minden etnikai csoport képviselteti magát", "Hétfőtől szombatig tart nyitva"],
